&quot;;<br>&gt; <br>&gt; <br>&gt;     // Look at non-diaginal case (example from Moler &amp; Van Loan, 2003)<br>&gt;     Eigen::Matrix&lt;stan::math::var, 2, 2&gt; E, E_diag, E_b, E_b_1;<br>&gt;     stan::math::var E11=-1, E22=-17, lp11;<br>&gt; <br>&gt;     E_diag &lt;&lt; E11, 0,<br>&gt;               0, E22;<br>&gt; <br>&gt;     E_b &lt;&lt; 1, 3, <br>&gt;            2, 4;<br>&gt; <br>&gt;     E_b_1 &lt;&lt; -2, 1.5,<br>&gt;              1, -.5;<br>&gt; <br>&gt;     E = E_b*E_diag*E_b_1;<br>&gt; <br>&gt;     std::cout &lt;&lt; &quot;The Matrix E is:
